from dataclasses import dataclass
from typing import Dict, List, Optional

@dataclass
class ThreatScenario:
    """Data class to represent threat scenarios"""
    scenario_id: str
    name: str
    threat_type: str
    impact_radius: float  # in kilometers
    probability: float   # 0-1 likelihood of occurrence
    base_severity: float # 0-1 base impact severity

class CitySimulation:
    def __init__(self, city_name: str, population: int, infrastructure: Dict):
        self.city_name = city_name
        self.population = population
        self.infrastructure = infrastructure
        self.scenarios: List[ThreatScenario] = []
        self.results: Dict = {}

    def add_threat_scenario(self, scenario: ThreatScenario) -> None:
        """Add a threat scenario to the simulation"""
        self.scenarios.append(scenario)

    def calculate_impact(self, scenario: ThreatScenario) -> Dict:
        """Calculate the impact of a threat scenario on the city"""
        # Generate random impact factors based on scenario parameters
        disruption = min(1.0, scenario.base_severity * random.uniform(0.5, 1.5))
        economic_loss = disruption * self.population * random.uniform(100, 1000)
        casualties = int(self.population * disruption * random.uniform(0.001, 0.01))

        # Calculate infrastructure damage
        infrastructure_damage = {}
        for infra_type, value in self.infrastructure.items():
            if random.random() < disruption:
                infrastructure_damage[infra_type] = min(1.0, value * random.uniform(0.1, 0.5))
            else:
                infrastructure_damage[infra_type] = 0.0

