            "disruption_level": disruption,
            "economic_loss_usd": economic_loss,
            "estimated_casualties": casualties,
            "infrastructure_damage": infrastructure_damage,
            "public_response": {
                "evacuation_needed": disruption > 0.3,
                "emergency_services_required": disruption > 0.5,
                "social_unrest_risk": disruption > 0.7
            }
        }

    def run_simulation(self, num_iterations: int = 1000) -> Dict:
        """Run the simulation for all added threat scenarios"""
        for scenario in self.scenarios:
            scenario_results = []
            for _ in range(num_iterations):
